D = '2026-09-28'
def ev(p, js): return p.evaluate(js)
def fuel(p, d=D): return ev(p, "JSON.parse(JSON.stringify(((S.logs['uadmin_%s'] || {}).fuel) || {}))" % d)
def score(p, d, pid='uadmin'): return ev(p, "dayScore('%s', '%s').score" % (pid, d))
def parts(p, d, pid='uadmin'): return ev(p, "dayScore('%s', '%s').parts.map(x => x.label + ' ' + x.pts + '/' + x.max).join(' · ')" % (pid, d))
def T(p, d=D, pid='uadmin'): return ev(p, "fuelTargets('%s', '%s')" % (pid, d))
def tap(p, k, v, where='#nu-day'):  # retried: under a heavy parallel run a tap can land while the page redraws
    sel = where + ' [data-a=fu-n][data-k=%s][data-v="%d"]' % (k, v); d = p.get_attribute(sel, 'data-d')
    val = lambda: p.evaluate("(((S.logs['uadmin_%s'] || {}).fuel) || {})['%s'] || 0" % (d, k))
    before = val()
    for attempt in range(3):
        p.click(sel); p.wait_for_timeout(250)
        if val() != before: return
def setnut(p, k, v): p.fill('#nut-' + k, str(v)); p.locator('#nut-' + k).blur(); p.wait_for_timeout(700)
def overflow(p): return p.evaluate('document.documentElement.scrollWidth > window.innerWidth + 1')
def mifflin(kg, cm, age, male): return 10 * kg + 6.25 * cm - 5 * age + (5 if male else -161)
r5 = lambda x: int(round(x / 5.0) * 5)

